class Solution:
    def findMedianSortedArrays(self, A, B):
        if len(A) > len(B): A, B = B, A
        m, n, half = len(A), len(B), (len(A) + len(B) + 1) // 2
        lo, hi = 0, m
        while lo <= hi:
            i = (lo + hi) // 2; j = half - i
            a_left = A[i-1] if i else float('-inf'); a_right = A[i] if i < m else float('inf')
            b_left = B[j-1] if j else float('-inf'); b_right = B[j] if j < n else float('inf')
            if a_left <= b_right and b_left <= a_right:
                if (m + n) % 2: return max(a_left, b_left)
                return (max(a_left, b_left) + min(a_right, b_right)) / 2
            if a_left > b_right: hi = i - 1
            else: lo = i + 1

class Solution:
    def findMedianSortedArrays(self, A, B):
        merged = sorted(A + B); n = len(merged)
        return float(merged[n // 2]) if n % 2 else (merged[n // 2 - 1] + merged[n // 2]) / 2

class Solution:
    def findMedianSortedArrays(self, A, B):
        n = len(A) + len(B); i = j = 0; prev = cur = 0
        for _ in range(n // 2 + 1):
            prev = cur
            if i < len(A) and (j >= len(B) or A[i] <= B[j]): cur = A[i]; i += 1
            else: cur = B[j]; j += 1
        return cur if n % 2 else (prev + cur) / 2

