class Solution:
    def convert(self, s, numRows):
        if numRows == 1 or numRows >= len(s): return s
        res = []; cycle = 2 * numRows - 2
        for r in range(numRows):
            for i in range(r, len(s), cycle):
                res.append(s[i])
                j = i + cycle - 2 * r
                if 0 < r < numRows - 1 and j < len(s): res.append(s[j])
        return ''.join(res)

