class Solution:
    def myAtoi(self, s):
        i, n = 0, len(s)
        while i < n and s[i] == ' ':
            i += 1
        sign = 1
        if i < n and s[i] in '+-':
            if s[i] == '-': sign = -1
            i += 1
        num = 0
        while i < n and s[i].isdigit():
            num = num * 10 + int(s[i])
            i += 1
        num *= sign
        return max(-2**31, min(2**31 - 1, num))

class Solution:
    def myAtoi(self, s):
        import re
        m = re.match(r' *([+-]?[0-9]+)', s)
