class Solution:
    def reverseKGroup(self, head, k):
        dummy = ListNode(); tail = dummy; cur = head
        while True:
            st = []; tmp = cur
            while tmp and len(st) < k: st.append(tmp); tmp = tmp.next
            if len(st) < k: tail.next = cur; break
            while st: tail.next = st.pop(); tail = tail.next
            tail.next = tmp; cur = tmp
        return dummy.next

