    def alienOrder(self, words):
        g = {c: set() for w in words for c in w}
        indeg = {c: 0 for c in g}
        for a, b in zip(words, words[1:]):
            for x, y in zip(a, b):
                if x != y:
                    if y not in g[x]:
                        g[x].add(y)
                        indeg[y] += 1
                    break
            else:
                if len(a) > len(b): return ''
