    def coinChange(self, coins, amount):
        dp = [0] + [float('inf')] * amount
        for a in range(1, amount + 1):
            for c in coins:
                if c <= a: dp[a] = min(dp[a], dp[a - c] + 1)
        return dp[amount] if dp[amount] != float('inf') else -1

class Solution:
    def coinChange(self, coins, amount):
        if amount == 0: return 0
        q = deque([(0, 0)]); seen = {0}
        while q:
            cur, steps = q.popleft()
            for c in coins:
                nxt = cur + c
                if nxt == amount: return steps + 1
                if nxt < amount and nxt not in seen: seen.add(nxt); q.append((nxt, steps + 1))
        return -1

class Solution:
    def coinChange(self, coins, amount):
        @lru_cache(None)
        def go(rem):
            if rem == 0: return 0
            if rem < 0: return float('inf')
            return 1 + min((go(rem - c) for c in coins), default=float('inf'))
        ans = go(amount)
        return -1 if ans == float('inf') else ans

