class Solution:
    def countComponents(self, n, edges):
        parent = list(range(n))
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        groups = n
        for a, b in edges:
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[ra] = rb
                groups -= 1
        return groups

class Solution:
    def countComponents(self, n, edges):
        g = [[] for _ in range(n)]
        for a, b in edges:
            g[a].append(b)
            g[b].append(a)
        seen = [False] * n
        groups = 0
        for s in range(n):
            if seen[s]: continue
            groups += 1
            seen[s] = True
            st = [s]
            while st:
                u = st.pop()
                for v in g[u]:
                    if not seen[v]:
                        seen[v] = True
                        st.append(v)
        return groups

