class Solution:
    def longestIncreasingPath(self, matrix):
        m, n = len(matrix), len(matrix[0])
        @lru_cache(None)
        def go(r, c):
            best = 1
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                a, b = r + dr, c + dc
                if 0 <= a < m and 0 <= b < n and matrix[a][b] > matrix[r][c]: best = max(best, 1 + go(a, b))
            return best
        return max(go(i, j) for i in range(m) for j in range(n))

class Solution:
    def longestIncreasingPath(self, matrix):
        m, n = len(matrix), len(matrix[0])
        indeg = [[0] * n for _ in range(m)]
        for i in range(m):
            for j in range(n):
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    a, b = i + dr, j + dc
                    if 0 <= a < m and 0 <= b < n and matrix[a][b] < matrix[i][j]: indeg[i][j] += 1
        q = deque((i, j) for i in range(m) for j in range(n) if indeg[i][j] == 0)
        layers = 0
        while q:
            layers += 1
            for _ in range(len(q)):
                r, c = q.popleft()
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    a, b = r + dr, c + dc
                    if 0 <= a < m and 0 <= b < n and matrix[a][b] > matrix[r][c]:
                        indeg[a][b] -= 1
                        if indeg[a][b] == 0: q.append((a, b))
        return layers

