class Solution:
    def minPatches(self, nums, n):
        arr = list(nums)
        patches = 0
        while True:
            sums = {0}
            for x in arr: sums |= {s + x for s in sums}
            missing = next((v for v in range(1, n + 1) if v not in sums), None)
            if missing is None: return patches
            arr.append(missing)
            patches += 1

