class Solution:
    def rob(self, root):
        def go(node):
            if not node: return 0, 0
            lr, ln = go(node.left)
            rr, rn = go(node.right)
            robbed = node.val + ln + rn
            skipped = max(lr, ln) + max(rr, rn)
            return robbed, skipped
        return max(go(root))

class Solution:
    def rob(self, root):
        memo = {}
        def best(node):
            if not node: return 0
            if node in memo: return memo[node]
            take = node.val
            if node.left: take += best(node.left.left) + best(node.left.right)
            if node.right: take += best(node.right.left) + best(node.right.right)
            memo[node] = max(take, best(node.left) + best(node.right))
            return memo[node]
        return best(root)

