class Solution:
    def reverseVowels(self, s):
        vowels = set('aeiouAEIOU')
        a = list(s)
        left, right = 0, len(a)-1
        while left < right:
            while left < right and a[left] not in vowels: left += 1
            while left < right and a[right] not in vowels: right -= 1
            a[left], a[right] = a[right], a[left]
            left, right = left+1, right-1
        return ''.join(a)

class Solution:
    def reverseVowels(self, s):
        vowels = set('aeiouAEIOU')
        stack = [c for c in s if c in vowels]
        res = []
        for c in s:
            res.append(stack.pop() if c in vowels else c)
        return ''.join(res)

class Solution:
    def reverseVowels(self, s):
        vowels = set('aeiouAEIOU')
        pos = [i for i, c in enumerate(s) if c in vowels]
        letters = [s[i] for i in pos][::-1]
        a = list(s)
        for i, c in zip(pos, letters): a[i] = c
        return ''.join(a)

