class SnakeGame:
    def __init__(self, width, height, food):
        self.w, self.h, self.food = width, height, [tuple(f) for f in food]
        self.body = [(0, 0)]
        self.score = 0
    def move(self, direction):
        dr, dc = {'U': (-1, 0), 'D': (1, 0), 'L': (0, -1), 'R': (0, 1)}[direction]
        r, c = self.body[-1][0] + dr, self.body[-1][1] + dc
        if not (0 <= r < self.h and 0 <= c < self.w): return -1
        if self.score < len(self.food) and (r, c) == self.food[self.score]:
            self.score += 1
        else:
            self.body.pop(0)
        if (r, c) in self.body: return -1
        self.body.append((r, c))
        return self.score

