class Solution:
    def sortTransformedArray(self, nums, a, b, c):
        f = lambda x: a * x * x + b * x + c
        n = len(nums)
        res = [0] * n
        l, r = 0, n - 1
        i = n - 1 if a >= 0 else 0
        while l <= r:
            fl, fr = f(nums[l]), f(nums[r])
            if a >= 0:
                if fl > fr:
                    res[i] = fl
                    l += 1
                else:
                    res[i] = fr
                    r -= 1
                i -= 1
            else:
