class Solution:
    def canMeasureWater(self, x, y, target):
        seen = {(0, 0)}
        q = deque([(0, 0)])
        while q:
            a, b = q.popleft()
            if target in (a, b, a + b): return True
            pour_ab = min(a, y - b)
            pour_ba = min(b, x - a)
            for nxt in ((x, b), (a, y), (0, b), (a, 0), (a - pour_ab, b + pour_ab), (a + pour_ba, b - pour_ba)):
                if nxt not in seen:
                    seen.add(nxt)
                    q.append(nxt)
        return False

