class Solution:
    def findLeaves(self, root):
        res = []
        def cut(node, out):
            if not node: return None
            if not node.left and not node.right:
                out.append(node.val)
                return None
            node.left = cut(node.left, out)
            node.right = cut(node.right, out)
            return node
        while root:
            out = []
            root = cut(root, out)
            res.append(out)
        return res

