    def canIWin(self, maxChoosableInteger, desiredTotal):
        m = maxChoosableInteger
        if desiredTotal <= 0: return True
        if m * (m + 1) // 2 < desiredTotal: return False
        memo = {}
        def win(rem, total):
            if rem in memo: return memo[rem]
            for x in rem:
                if x >= total or not win(tuple(y for y in rem if y != x), total - x):
                    memo[rem] = True
                    return True
            memo[rem] = False
            return False
        return win(tuple(range(1, m + 1)), desiredTotal)

