        for a, b, c in transactions:
            bal[a] -= c
            bal[b] += c
        debts = [v for v in bal.values() if v]
        m = len(debts)
        total = [0] * (1 << m)
        dp = [0] * (1 << m)
        for mask in range(1, 1 << m):
            low = (mask & -mask).bit_length() - 1
            total[mask] = total[mask & (mask - 1)] + debts[low]
            best = 0
            for i in range(m):
                if mask >> i & 1: best = max(best, dp[mask ^ (1 << i)])
