    def __init__(self, sentences, times):
        self.root = {}
        self.cur = ''
        self.node = self.root
        for s, t in zip(sentences, times): self._add(s, t)
    def _add(self, s, t):
        node = self.root
        for ch in s: node = node.setdefault(ch, {})
        node['#'] = node.get('#', 0) + t
    def _collect(self, node, prefix, out):
        for ch, child in node.items():
            if ch == '#': out.append((-child, prefix))
            else: self._collect(child, prefix + ch, out)
    def input(self, c):
        if c == '#':
            self._add(self.cur, 1)
            self.cur = ''
            self.node = self.root
            return []
        self.cur += c
        if self.node is not None: self.node = self.node.get(c)
        if self.node is None: return []
        out = []
        self._collect(self.node, self.cur, out)
        return [s for _, s in sorted(out)[:3]]

