class Solution:
    def canPartitionKSubsets(self, nums, k):
        total = sum(nums)
        if total % k: return False
        target = total // k
        nums = sorted(nums, reverse=True)
        if nums[0] > target: return False
        buckets = [0] * k
        def go(i):
            if i == len(nums): return True
            seen = set()
            for j in range(k):
                if buckets[j] + nums[i] <= target and buckets[j] not in seen:
                    seen.add(buckets[j])
                    buckets[j] += nums[i]
                    if go(i + 1): return True
                    buckets[j] -= nums[i]
            return False
        return go(0)

