    def canPartitionKSubsets(self, nums, k):
        total = sum(nums)
        if total % k: return False
        target = total // k
        n = len(nums)
        dp = [-1] * (1 << n)
        dp[0] = 0
        for mask in range(1 << n):
            if dp[mask] < 0: continue
            for i in range(n):
                if not mask >> i & 1 and dp[mask] + nums[i] <= target:
                    dp[mask | 1 << i] = (dp[mask] + nums[i]) % target
        return dp[-1] == 0

