class Solution:
    def countPalindromicSubsequences(self, s):
        MOD = 10 ** 9 + 7
        n = len(s)
        dp = [[0] * n for _ in range(n)]
        for i in range(n): dp[i][i] = 1
        for length in range(2, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                if s[i] != s[j]:
                    dp[i][j] = dp[i + 1][j] + dp[i][j - 1] - dp[i + 1][j - 1]
                else:
                    lo, hi = i + 1, j - 1
                    while lo <= hi and s[lo] != s[i]: lo += 1
                    while lo <= hi and s[hi] != s[i]: hi -= 1
                    if lo > hi: dp[i][j] = dp[i + 1][j - 1] * 2 + 2
                    elif lo == hi: dp[i][j] = dp[i + 1][j - 1] * 2 + 1
                    else: dp[i][j] = dp[i + 1][j - 1] * 2 - dp[lo + 1][hi - 1]
                dp[i][j] %= MOD
        return dp[0][n - 1]

class Solution:
    def countPalindromicSubsequences(self, s):
        MOD = 10 ** 9 + 7
        @lru_cache(None)
        def f(i, j):
            if i > j: return 0
            total = 0
            for ch in 'abcd':
                l = s.find(ch, i, j + 1)
                if l == -1: continue
                r = s.rfind(ch, i, j + 1)
                if l == r: total += 1
                else: total += 2 + f(l + 1, r - 1)
            return total % MOD
        return f(0, len(s) - 1)

