class Solution:
    def evaluate(self, expression):
        tokens = expression.replace('(', ' ( ').replace(')', ' ) ').split()
        scopes = [{}]
        pos = 0
        def ev():
            nonlocal pos
            t = tokens[pos]
            if t != '(':
                pos += 1
                if t.lstrip('-').isdigit(): return int(t)
                for sc in reversed(scopes):
                    if t in sc: return sc[t]
            pos += 1
            op = tokens[pos]
            pos += 1
            if op == 'add' or op == 'mult':
                a = ev()
                b = ev()
                pos += 1
                return a + b if op == 'add' else a * b
            scopes.append({})
            while True:
                if tokens[pos] == '(' or tokens[pos + 1] == ')':
                    v = ev()
                    pos += 1
                    scopes.pop()
                    return v
                name = tokens[pos]
                pos += 1
                scopes[-1][name] = ev()
        return ev()

class Solution:
    def evaluate(self, expression):
        def split(s):
            parts, depth, cur = [], 0, ''
            for ch in s:
                if ch == ' ' and depth == 0:
                    parts.append(cur)
                    cur = ''
                    continue
                if ch == '(': depth += 1
                if ch == ')': depth -= 1
                cur += ch
            parts.append(cur)
            return parts
        def ev(s, env):
            if s[0] != '(':
                return int(s) if s.lstrip('-').isdigit() else env[s]
            parts = split(s[1:-1])
            if parts[0] == 'add': return ev(parts[1], env) + ev(parts[2], env)
            if parts[0] == 'mult': return ev(parts[1], env) * ev(parts[2], env)
            env = dict(env)
            for i in range(1, len(parts) - 1, 2): env[parts[i]] = ev(parts[i + 1], env)
            return ev(parts[-1], env)
        return ev(expression, {})

