class Solution:
    def areSentencesSimilarTwo(self, sentence1, sentence2, similarPairs):
        if len(sentence1) != len(sentence2): return False
        g = defaultdict(set)
        for a, b in similarPairs:
            g[a].add(b)
            g[b].add(a)
        def reach(a, b):
            seen, st = {a}, [a]
            while st:
                u = st.pop()
                if u == b: return True
                for v in g[u]:
                    if v not in seen:
                        seen.add(v)
                        st.append(v)
            return False
        return all(a == b or reach(a, b) for a, b in zip(sentence1, sentence2))

