class Solution:
    def cherryPickup(self, grid):
        n = len(grid)
        NEG = float('-inf')
        dp = [[NEG] * n for _ in range(n)]
        dp[0][0] = grid[0][0]
        for k in range(1, 2 * n - 1):
            new = [[NEG] * n for _ in range(n)]
            for i in range(max(0, k - n + 1), min(n, k + 1)):
                for j in range(max(0, k - n + 1), min(n, k + 1)):
                    if grid[i][k - i] == -1 or grid[j][k - j] == -1: continue
                    best = max(dp[i][j], dp[i - 1][j] if i else NEG, dp[i][j - 1] if j else NEG, dp[i - 1][j - 1] if i and j else NEG)
                    if best == NEG: continue
                    gain = grid[i][k - i] + (grid[j][k - j] if i != j else 0)
                    new[i][j] = best + gain
            dp = new
        return max(0, dp[n - 1][n - 1])

class Solution:
    def cherryPickup(self, grid):
        n = len(grid)
        NEG = float('-inf')
        @lru_cache(None)
        def f(k, i, j):
            ci, cj = k - i, k - j
            if min(ci, cj) < 0 or max(i, j, ci, cj) >= n or grid[i][ci] == -1 or grid[j][cj] == -1: return NEG
            if k == 2 * n - 2: return grid[i][ci]
            gain = grid[i][ci] + (grid[j][cj] if i != j else 0)
            return gain + max(f(k + 1, i, j), f(k + 1, i + 1, j), f(k + 1, i, j + 1), f(k + 1, i + 1, j + 1))
        return max(0, f(0, 0, 0))

