        if source == target: return 0
        stop_routes = defaultdict(list)
        for i, r in enumerate(routes):
            for s in r: stop_routes[s].append(i)
        dist, used = {source: 0}, set()
        q = deque([source])
        while q:
            s = q.popleft()
            for r in stop_routes[s]:
                if r in used: continue
                used.add(r)
                for t in routes[r]:
                    if t not in dist:
                        dist[t] = dist[s] + 1
                        q.append(t)
