    def distanceK(self, root, target, k):
        ans = []
        def collect(node, d):
            if not node or d > k: return
            if d == k:
                ans.append(node.val)
                return
            collect(node.left, d + 1)
            collect(node.right, d + 1)
        def go(node):
            if not node: return -1
            if node is target:
                collect(node, 0)
                return 0
            l, r = go(node.left), go(node.right)
            if l != -1:
                if l + 1 == k: ans.append(node.val)
                else: collect(node.right, l + 2)
                return l + 1
            if r != -1:
                if r + 1 == k: ans.append(node.val)
                else: collect(node.left, r + 2)
                return r + 1
            return -1
