    def constructFromPrePost(self, preorder, postorder):
        idx = {v: i for i, v in enumerate(postorder)}
        def build(i, j, n):
            if n == 0: return None
            root = TreeNode(preorder[i])
            if n == 1: return root
            L = idx[preorder[i + 1]] - j + 1
