    def __init__(self, encoding):
        self.e = encoding
        self.i = 0
    def next(self, n):
        while self.i < len(self.e):
            if self.e[self.i] >= n:
                self.e[self.i] -= n
                return self.e[self.i + 1]
            n -= self.e[self.i]
            self.i += 2
        return -1

class RLEIterator:
    def __init__(self, encoding):
        self.q = deque((encoding[i], encoding[i + 1]) for i in range(0, len(encoding), 2))
    def next(self, n):
        while self.q:
            c, v = self.q[0]
            if c >= n:
                self.q[0] = (c - n, v)
                return v
            n -= c
            self.q.popleft()
        return -1

