    def next(self, price):
        self.p.append(price); span = 1
        i = len(self.p) - 2
        while i >= 0 and self.p[i] <= price:
            span += 1; i -= 1
        return span

class StockSpanner:
    def __init__(self): self.st = []; self.i = -1
    def next(self, price):
        self.i += 1
        while self.st and self.st[-1][1] <= price: self.st.pop()
        span = self.i - (self.st[-1][0] if self.st else -1)
        self.st.append((self.i, price))
        return span

