class Solution:
    def totalFruit(self, fruits):
        cnt, left, best = {}, 0, 0
        for right, f in enumerate(fruits):
            cnt[f] = cnt.get(f, 0) + 1
            while len(cnt) > 2:
                cnt[fruits[left]] -= 1
                if cnt[fruits[left]] == 0: del cnt[fruits[left]]
                left += 1
            best = max(best, right - left + 1)
        return best

class Solution:
    def totalFruit(self, fruits):
        a = b = -1
        cur = cur_b = best = 0
        for f in fruits:
            cur = cur + 1 if f in (a, b) else cur_b + 1
            cur_b = cur_b + 1 if f == b else 1
            if f != b: a, b = b, f
            best = max(best, cur)
        return best

