class Solution:
    def snakesAndLadders(self, board):
        n = len(board)
        def cell(s):
            r, c = divmod(s - 1, n)
            row = n - 1 - r
            col = c if r % 2 == 0 else n - 1 - c
            return row, col
        seen, q = {1}, deque([(1, 0)])
        while q:
            s, d = q.popleft()
            for nxt in range(s + 1, min(s + 6, n * n) + 1):
                r, c = cell(nxt)
                if board[r][c] != -1: nxt = board[r][c]
                if nxt == n * n: return d + 1
                if nxt not in seen: seen.add(nxt); q.append((nxt, d + 1))
        return -1

class Solution:
    def snakesAndLadders(self, board):
        n = len(board); cells = [None]; ltr = True
        for row in range(n - 1, -1, -1):
            cols = range(n) if ltr else range(n - 1, -1, -1)
            for col in cols: cells.append(board[row][col])
            ltr = not ltr
        dist = {1: 0}; q = deque([1])
        while q:
            s = q.popleft()
            for nxt in range(s + 1, min(s + 6, n * n) + 1):
                dest = cells[nxt] if cells[nxt] != -1 else nxt
                if dest == n * n: return dist[s] + 1
                if dest not in dist: dist[dest] = dist[s] + 1; q.append(dest)
        return -1

