class Solution:
    def reverseOnlyLetters(self, s):
        chars = list(s)
        i, j = 0, len(chars) - 1
        while i < j:
            if not chars[i].isalpha(): i += 1
            elif not chars[j].isalpha(): j -= 1
            else:
                chars[i], chars[j] = chars[j], chars[i]
                i += 1
                j -= 1
        return ''.join(chars)

class Solution:
    def reverseOnlyLetters(self, s):
        letters = [ch for ch in s if ch.isalpha()]
        out = []
        for ch in s:
            out.append(letters.pop() if ch.isalpha() else ch)
        return ''.join(out)

