class Solution:
    def maxSubarraySumCircular(self, nums):
        n = len(nums); best = float('-inf')
        for i in range(n):
            s = 0
            for k in range(n): s += nums[(i + k) % n]; best = max(best, s)
        return best

class Solution:
    def maxSubarraySumCircular(self, nums):
        def kadane(arr, f):
            cur = best = arr[0]
            for x in arr[1:]: cur = f(x, cur + x); best = f(best, cur)
            return best
        mx = kadane(nums, max); mn = kadane(nums, min); total = sum(nums)
        return mx if mx < 0 else max(mx, total - mn)

