class Solution:
    def numMusicPlaylists(self, n, goal, k):
        MOD = 10 ** 9 + 7
        dp = [[0] * (n + 1) for _ in range(goal + 1)]
        dp[0][0] = 1
        for i in range(1, goal + 1):
            for j in range(1, min(i, n) + 1):
                dp[i][j] = dp[i - 1][j - 1] * (n - j + 1) % MOD
                if j > k:
                    dp[i][j] = (dp[i][j] + dp[i - 1][j] * (j - k)) % MOD
        return dp[goal][n]

class Solution:
    def numMusicPlaylists(self, n, goal, k):
        MOD = 10 ** 9 + 7
        @lru_cache(None)
        def go(i, j):
            if i == 0: return 1 if j == 0 else 0
            res = go(i - 1, j - 1) * (n - j + 1)
            if j > k: res += go(i - 1, j) * (j - k)
            return res % MOD
        return go(goal, n)

