class Solution:
    def minMalwareSpread(self, graph, initial):
        n = len(graph)
        parent = list(range(n))
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        for i in range(n):
            for j in range(i + 1, n):
                if graph[i][j]: parent[find(i)] = find(j)
        size = Counter(find(i) for i in range(n))
        infected = Counter(find(i) for i in initial)
        best, ans = -1, min(initial)
        for i in sorted(initial):
            r = find(i)
            gain = size[r] if infected[r] == 1 else 0
            if gain > best:
                best, ans = gain, i
        return ans

class Solution:
    def minMalwareSpread(self, graph, initial):
        n = len(graph)
        def spread(init):
            seen = set(init)
            q = deque(init)
            while q:
                u = q.popleft()
                for v in range(n):
                    if graph[u][v] and v not in seen:
                        seen.add(v)
                        q.append(v)
            return len(seen)
        best, ans = n + 1, None
        for x in sorted(initial):
            cnt = spread([y for y in initial if y != x])
            if cnt < best:
                best, ans = cnt, x
        return ans

