class Solution:
    def numSubarraysWithSum(self, nums, goal):
        count, prefix, seen = 0, 0, {0: 1}
        for x in nums:
            prefix += x
            count += seen.get(prefix - goal, 0)
            seen[prefix] = seen.get(prefix, 0) + 1
        return count

class Solution:
    def numSubarraysWithSum(self, nums, goal):
        def at_most(g):
            if g < 0: return 0
            left = total = res = 0
            for right, x in enumerate(nums):
                total += x
                while total > g:
                    total -= nums[left]
                    left += 1
                res += right - left + 1
            return res
        return at_most(goal) - at_most(goal - 1)

