class Solution:
    def minFallingPathSum(self, matrix):
        n = len(matrix)
        @lru_cache(None)
        def f(i, j):
            if j < 0 or j >= n: return float('inf')
            if i == n - 1: return matrix[i][j]
            return matrix[i][j] + min(f(i + 1, j - 1), f(i + 1, j), f(i + 1, j + 1))
        return min(f(0, j) for j in range(n))

