class Solution:
    def shortestBridge(self, grid):
        n = len(grid)
        q, seen = deque(), set()
        def dfs(r, c):
            if not (0 <= r < n and 0 <= c < n) or (r, c) in seen or grid[r][c] != 1: return
            seen.add((r, c))
            q.append((r, c, 0))
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)): dfs(r + dr, c + dc)
        found = False
        for i in range(n):
            for j in range(n):
                if grid[i][j] == 1 and not found:
                    dfs(i, j)
                    found = True
        while q:
            r, c, d = q.popleft()
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                a, b = r + dr, c + dc
                if 0 <= a < n and 0 <= b < n and (a, b) not in seen:
                    if grid[a][b] == 1: return d
                    seen.add((a, b))
                    q.append((a, b, d + 1))

class Solution:
    def shortestBridge(self, grid):
        n = len(grid)
        seen = {}
        def dfs(r, c, lab):
            if not (0 <= r < n and 0 <= c < n) or (r, c) in seen or grid[r][c] != 1: return
            seen[(r, c)] = lab
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)): dfs(r + dr, c + dc, lab)
        lab = 0
        for i in range(n):
            for j in range(n):
                if grid[i][j] == 1 and (i, j) not in seen:
                    dfs(i, j, lab)
                    lab += 1
        a = [p for p, l in seen.items() if l == 0]
        b = [p for p, l in seen.items() if l == 1]
        return min(abs(x1 - x2) + abs(y1 - y2) for x1, y1 in a for x2, y2 in b) - 1

