class Solution:
    def minAreaRect(self, points):
        pts = set(map(tuple, points))
        best = float('inf')
        for x1, y1 in pts:
            for x2, y2 in pts:
                if x1 < x2 and y1 < y2 and (x1, y2) in pts and (x2, y1) in pts:
                    best = min(best, (x2 - x1) * (y2 - y1))
        return best if best != float('inf') else 0

class Solution:
    def minAreaRect(self, points):
        cols = defaultdict(list)
        for x, y in points: cols[x].append(y)
        last, best = {}, float('inf')
        for x in sorted(cols):
            ys = sorted(cols[x])
            for i in range(len(ys)):
                for j in range(i):
                    key = (ys[j], ys[i])
                    if key in last: best = min(best, (x - last[key]) * (ys[i] - ys[j]))
                    last[key] = x
        return best if best != float('inf') else 0

