class Solution:
    def removeStones(self, stones):
        parent = {}
        def find(x):
            parent.setdefault(x, x)
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        for r, c in stones:
            parent[find(r)] = find(~c)
        return len(stones) - len({find(x) for x in parent})

class Solution:
    def removeStones(self, stones):
        n = len(stones)
        seen, comps = set(), 0
        for i in range(n):
            if i in seen: continue
            comps += 1
            st = [i]
            seen.add(i)
            while st:
                u = st.pop()
                for v in range(n):
                    if v not in seen and (stones[v][0] == stones[u][0] or stones[v][1] == stones[u][1]):
                        seen.add(v)
                        st.append(v)
        return n - comps

