class Solution:
    def regionsBySlashes(self, grid):
        n = len(grid)
        parent = list(range(4 * n * n))
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        def union(a, b): parent[find(a)] = find(b)
        for i in range(n):
            for j in range(n):
                base = 4 * (i * n + j)
                c = grid[i][j]
                if c == '/':
                    union(base, base + 3)
                    union(base + 1, base + 2)
                elif c == '\\':
                    union(base, base + 1)
                    union(base + 2, base + 3)
                else:
                    for k in (1, 2, 3): union(base, base + k)
                if i + 1 < n: union(base + 2, 4 * ((i + 1) * n + j))
                if j + 1 < n: union(base + 1, 4 * (i * n + j + 1) + 3)
        return len({find(x) for x in range(4 * n * n)})

class Solution:
    def regionsBySlashes(self, grid):
        n = len(grid)
        g = [[0] * (3 * n) for _ in range(3 * n)]
        for i in range(n):
            for j in range(n):
                if grid[i][j] == '/':
                    for k in range(3): g[3 * i + k][3 * j + 2 - k] = 1
                elif grid[i][j] == '\\':
                    for k in range(3): g[3 * i + k][3 * j + k] = 1
        regions = 0
        for i in range(3 * n):
            for j in range(3 * n):
                if g[i][j] == 0:
                    regions += 1
                    st = [(i, j)]
                    g[i][j] = 1
                    while st:
                        x, y = st.pop()
                        for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                            a, b = x + dx, y + dy
                            if 0 <= a < 3 * n and 0 <= b < 3 * n and g[a][b] == 0:
                                g[a][b] = 1
                                st.append((a, b))
        return regions

