class Solution:
    def minCameraCover(self, root):
        self.cams = 0
        def dfs(node):
            if not node:
                return 2
            l, r = dfs(node.left), dfs(node.right)
            if l == 0 or r == 0:
                self.cams += 1
                return 1
            if l == 1 or r == 1:
                return 2
            return 0
        if dfs(root) == 0:
            self.cams += 1
        return self.cams

class Solution:
    def minCameraCover(self, root):
        INF = 10 ** 9
        def dfs(node):
            if not node:
                return (INF, 0, 0)
            la, lb, lc = dfs(node.left)
            ra, rb, rc = dfs(node.right)
            a = 1 + min(la, lb, lc) + min(ra, rb, rc)
            b = min(la + min(ra, rb), ra + min(la, lb))
            c = lb + rb
            return (a, b, c)
        a, b, c = dfs(root)
        return min(a, b)

