class Solution:
    def uniquePathsIII(self, grid):
        m, n = len(grid), len(grid[0])
        empty = 0
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 1: si, sj = i, j
                if grid[i][j] != -1: empty += 1
        def dfs(i, j, left):
            if grid[i][j] == 2: return 1 if left == 0 else 0
            old, grid[i][j] = grid[i][j], -1
            total = 0
            for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                a, b = i + di, j + dj
                if 0 <= a < m and 0 <= b < n and grid[a][b] != -1:
                    total += dfs(a, b, left - 1)
            grid[i][j] = old
            return total
        return dfs(si, sj, empty - 1)

class Solution:
    def uniquePathsIII(self, grid):
        m, n = len(grid), len(grid[0])
        full = 0
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 1: start = (i, j)
                if grid[i][j] != -1: full |= 1 << (i * n + j)
        @lru_cache(None)
        def go(i, j, mask):
            if grid[i][j] == 2: return 1 if mask == full else 0
            total = 0
            for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                a, b = i + di, j + dj
                if 0 <= a < m and 0 <= b < n and grid[a][b] != -1 and not (mask >> (a * n + b)) & 1:
                    total += go(a, b, mask | (1 << (a * n + b)))
            return total
        return go(start[0], start[1], 1 << (start[0] * n + start[1]))

