class Solution:
    def mincostTickets(self, days, costs):
        last = days[-1]
        travel = set(days)
        dp = [0] * (last + 1)
        for d in range(1, last + 1):
            if d not in travel:
                dp[d] = dp[d - 1]
            else:
                dp[d] = min(dp[d - 1] + costs[0],
                            dp[max(0, d - 7)] + costs[1],
                            dp[max(0, d - 30)] + costs[2])
        return dp[last]

class Solution:
    def mincostTickets(self, days, costs):
        n = len(days)
        @lru_cache(None)
        def go(i):
            if i == n:
                return 0
            best = float("inf")
            for c, span in ((costs[0], 1), (costs[1], 7), (costs[2], 30)):
                j = i
                while j < n and days[j] < days[i] + span:
                    j += 1
                best = min(best, c + go(j))
            return best
        return go(0)

