class Solution:
    def minimumSemesters(self, n, relations):
        g = defaultdict(list)
        for a, b in relations: g[a].append(b)
        state = {}
        def depth(u):
            if u in state: return state[u] if state[u] else -1
            state[u] = 0
            best = 1
            for v in g[u]:
                d = depth(v)
                if d == -1: return -1
                best = max(best, d + 1)
            state[u] = best
            return best
        longest = 0
        for u in range(1, n + 1):
            d = depth(u)
            if d == -1: return -1
            longest = max(longest, d)
        return longest

