class Solution:
    def minCostToSupplyWater(self, n, wells, pipes):
        edges = [(c, 0, i + 1) for i, c in enumerate(wells)] + [(c, a, b) for a, b, c in pipes]
        edges.sort()
        parent = list(range(n + 1))
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
