        g = defaultdict(list)
        for i, c in enumerate(wells):
            g[0].append((c, i + 1))
            g[i + 1].append((c, 0))
        for a, b, c in pipes:
            g[a].append((c, b))
            g[b].append((c, a))
        seen, heap, total = set(), [(0, 0)], 0
        while heap and len(seen) < n + 1:
            c, u = heappop(heap)
            if u in seen: continue
