        while q:
            for _ in range(len(q)):
                cx, cy = q.popleft()
                if (cx, cy) == (x, y): return steps
                for dx, dy in ((1, 2), (2, 1), (2, -1), (1, -2), (-1, -2), (-2, -1), (-2, 1), (-1, 2)):
