    def minFlips(self, mat):
        m, n = len(mat), len(mat[0])
        start = sum(mat[i][j] << (i * n + j) for i in range(m) for j in range(n))
        masks = []
        for i in range(m):
            for j in range(n):
                mask = 1 << (i * n + j)
                for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    a, b = i + di, j + dj
                    if 0 <= a < m and 0 <= b < n: mask |= 1 << (a * n + b)
                masks.append(mask)
