    def isSolvable(self, words, result):
        weight = defaultdict(int)
        leading = set()
        for w in words:
            for i, ch in enumerate(reversed(w)): weight[ch] += 10 ** i
            if len(w) > 1: leading.add(w[0])
        for i, ch in enumerate(reversed(result)): weight[ch] -= 10 ** i
