        used = [False] * 10
        def go(k, total):
            if k == len(letters): return total == 0
            ch = letters[k]
            for d in range(10):
                if used[d] or (d == 0 and ch in leading): continue
                used[d] = True
                if go(k + 1, total + weight[ch] * d): return True
                used[d] = False
            return False
        return go(0, 0)

