    def findTheCity(self, n, edges, distanceThreshold):
        INF = float('inf')
        d = [[INF] * n for _ in range(n)]
        for i in range(n): d[i][i] = 0
        for u, v, w in edges:
            d[u][v] = d[v][u] = w
        for k in range(n):
