class Solution:
    def findTheCity(self, n, edges, distanceThreshold):
        g = defaultdict(list)
        for u, v, w in edges:
            g[u].append((v, w))
            g[v].append((u, w))
        best, city = n + 1, -1
        for s in range(n):
            dist = {s: 0}
            heap = [(0, s)]
            while heap:
                d, u = heappop(heap)
                if d > dist[u]: continue
                for v, w in g[u]:
                    if d + w < dist.get(v, float('inf')):
                        dist[v] = d + w
                        heappush(heap, (d + w, v))
