        mx, mn = deque(), deque()
        left = best = 0
        for right, x in enumerate(nums):
            while mx and mx[-1] < x: mx.pop()
            mx.append(x)
            while mn and mn[-1] > x: mn.pop()
            mn.append(x)
            while mx[0] - mn[0] > limit:
                if mx[0] == nums[left]: mx.popleft()
                if mn[0] == nums[left]: mn.popleft()
                left += 1
            best = max(best, right - left + 1)
        return best

class Solution:
    def longestSubarray(self, nums, limit):
        mx, mn = [], []
        left = best = 0
        for right, x in enumerate(nums):
            heappush(mx, (-x, right))
            heappush(mn, (x, right))
            while -mx[0][0] - mn[0][0] > limit:
                left = min(mx[0][1], mn[0][1]) + 1
                while mx[0][1] < left: heappop(mx)
                while mn[0][1] < left: heappop(mn)
            best = max(best, right - left + 1)
        return best

