        adj = defaultdict(list)
        for a, b in connections: adj[a].append(b); adj[b].append(a)
        seen, q, changes = {0}, deque([0]), 0
        while q:
            c = q.popleft()
            for nxt in adj[c]:
                if nxt not in seen:
                    if (c, nxt) in edges: changes += 1
