class Solution:
    def minReorder(self, n, connections):
        adj = defaultdict(list)
        for a, b in connections: adj[a].append((b, 1)); adj[b].append((a, 0))
        def go(city, parent):
            total = 0
            for nxt, cost in adj[city]:
                if nxt != parent: total += cost + go(nxt, city)
            return total
        return go(0, -1)

