        self.cur = url
        self.fwd_st = []
    def back(self, steps):
        while steps and self.back_st:
            self.fwd_st.append(self.cur)
            self.cur = self.back_st.pop()
            steps -= 1
        return self.cur
    def forward(self, steps):
        while steps and self.fwd_st:
