class Solution:
    def minCost(self, houses, cost, m, n, target):
        INF = float('inf')
        @lru_cache(None)
        def f(i, prev, t):
            if t > target: return INF
            if i == m: return 0 if t == target else INF
            best = INF
            for c in range(1, n + 1):
                if houses[i] and houses[i] != c: continue
                extra = 0 if houses[i] else cost[i][c - 1]
                best = min(best, extra + f(i + 1, c, t + (c != prev)))
            return best
        ans = f(0, 0, 0)
        return -1 if ans >= INF else ans

class Solution:
    def minCost(self, houses, cost, m, n, target):
        INF = float('inf')
        dp = [[[INF] * (target + 1) for _ in range(n + 1)] for _ in range(m)]
        for i in range(m):
            for c in range(1, n + 1):
                if houses[i] and houses[i] != c: continue
                extra = 0 if houses[i] else cost[i][c - 1]
                if i == 0:
                    dp[0][c][1] = extra
                    continue
                for t in range(1, target + 1):
                    best = INF
                    for pc in range(1, n + 1):
                        tt = t if pc == c else t - 1
                        if tt >= 1: best = min(best, dp[i - 1][pc][tt])
                    if best < INF: dp[i][c][t] = best + extra
        ans = min(dp[m - 1][c][target] for c in range(1, n + 1))
        return -1 if ans == INF else ans

