        n = len(rains)
        nxt, last = [n] * n, {}
        for i in range(n - 1, -1, -1):
            if rains[i]:
                nxt[i] = last.get(rains[i], n)
                last[rains[i]] = i
        ans, full, heap = [1] * n, set(), []
        for i, lake in enumerate(rains):
            if lake:
                if lake in full: return []
                full.add(lake)
                ans[i] = -1
                if nxt[i] < n: heappush(heap, (nxt[i], lake))
            elif heap:
                _, l = heappop(heap)
                full.discard(l)
                ans[i] = l
        return ans

