class Solution:
    def findCriticalAndPseudoCriticalEdges(self, n, edges):
        order = sorted(range(len(edges)), key=lambda i: edges[i][2])
        def mst(skip=-1, force=-1):
            parent = list(range(n))
            def find(x):
                while parent[x] != x:
                    parent[x] = parent[parent[x]]
                    x = parent[x]
                return x
            w = used = 0
            if force >= 0:
                a, b, c = edges[force]
                parent[find(a)] = find(b)
                w, used = c, 1
            for i in order:
                if i == skip: continue
                a, b, c = edges[i]
                ra, rb = find(a), find(b)
                if ra != rb:
                    parent[ra] = rb
                    w += c
                    used += 1
            return w if used == n - 1 else float('inf')
        base = mst()
        crit, pseudo = [], []
        for i in range(len(edges)):
            if mst(skip=i) > base: crit.append(i)
            elif mst(force=i) == base: pseudo.append(i)
        return [crit, pseudo]

class Solution:
    def findCriticalAndPseudoCriticalEdges(self, n, edges):
        best, trees = float('inf'), []
        for combo in combinations(range(len(edges)), n - 1):
            parent = list(range(n))
            def find(x):
                while parent[x] != x:
                    parent[x] = parent[parent[x]]
                    x = parent[x]
                return x
            ok = True
            for i in combo:
                ra, rb = find(edges[i][0]), find(edges[i][1])
                if ra == rb:
                    ok = False
                    break
                parent[ra] = rb
            if not ok: continue
            w = sum(edges[i][2] for i in combo)
            if w < best: best, trees = w, [set(combo)]
            elif w == best: trees.append(set(combo))
        allin = set.intersection(*trees)
        anyin = set.union(*trees)
        return [sorted(allin), sorted(anyin - allin)]

