class Solution:
    def getLengthOfOptimalCompression(self, s, k):
        n = len(s)
        @lru_cache(None)
        def go(i, left):
            if left < 0: return float('inf')
            if i >= n - left: return 0
            best = go(i + 1, left - 1)
            same = diff = 0
            for j in range(i, n):
                if s[j] == s[i]: same += 1
                else: diff += 1
                if diff > left: break
                length = 1 if same == 1 else 1 + len(str(same))
                best = min(best, length + go(j + 1, left - diff))
            return best
        return go(0, k)

class Solution:
    def getLengthOfOptimalCompression(self, s, k):
        def rle(t):
            out, i = 0, 0
            while i < len(t):
                j = i
                while j < len(t) and t[j] == t[i]: j += 1
                out += 1 + (len(str(j - i)) if j - i > 1 else 0)
                i = j
            return out
        best = rle(s)
        for r in range(1, k + 1):
            for drop in combinations(range(len(s)), r):
                keep = ''.join(s[i] for i in range(len(s)) if i not in drop)
                best = min(best, rle(keep))
        return best

