class Solution:
    def maxNumEdgesToRemove(self, n, edges):
        pa, pb = list(range(n + 1)), list(range(n + 1))
        def find(p, x):
            while p[x] != x:
                p[x] = p[p[x]]
                x = p[x]
            return x
        def union(p, a, b):
            ra, rb = find(p, a), find(p, b)
            if ra == rb: return False
            p[ra] = rb
            return True
        used = 0
        for t, a, b in edges:
            if t == 3:
                ua, ub = union(pa, a, b), union(pb, a, b)
                if ua or ub: used += 1
        for t, a, b in edges:
            if t == 1 and union(pa, a, b): used += 1
            elif t == 2 and union(pb, a, b): used += 1
        ca = len({find(pa, i) for i in range(1, n + 1)})
        cb = len({find(pb, i) for i in range(1, n + 1)})
        return len(edges) - used if ca == 1 and cb == 1 else -1

class Solution:
    def maxNumEdgesToRemove(self, n, edges):
        def find(p, x):
            while p[x] != x:
                p[x] = p[p[x]]
                x = p[x]
            return x
        def union(p, a, b):
            ra, rb = find(p, a), find(p, b)
            if ra == rb: return False
            p[ra] = rb
            return True
        shared = list(range(n + 1))
        s = sum(1 for t, a, b in edges if t == 3 and union(shared, a, b))
        for kind in (1, 2):
            p = shared[:]
            for t, a, b in edges:
                if t == kind: union(p, a, b)
            if len({find(p, i) for i in range(1, n + 1)}) != 1: return -1
        return len(edges) - (s + 2 * (n - 1 - s))

