class Solution:
    def minCost(self, maxTime, edges, passingFees):
        n = len(passingFees)
        INF = float('inf')
        dp = [[INF] * n for _ in range(maxTime + 1)]
        dp[0][0] = passingFees[0]
        for t in range(1, maxTime + 1):
            for u, v, w in edges:
                if w <= t:
                    if dp[t - w][u] + passingFees[v] < dp[t][v]: dp[t][v] = dp[t - w][u] + passingFees[v]
                    if dp[t - w][v] + passingFees[u] < dp[t][u]: dp[t][u] = dp[t - w][v] + passingFees[u]
        ans = min(dp[t][n - 1] for t in range(maxTime + 1))
        return ans if ans < INF else -1

class Solution:
    def minCost(self, maxTime, edges, passingFees):
        n = len(passingFees)
        g = defaultdict(list)
        for u, v, w in edges:
            g[u].append((v, w))
            g[v].append((u, w))
        best = {}
        pq = [(passingFees[0], 0, 0)]
        while pq:
            cost, t, u = heappop(pq)
            if u == n - 1: return cost
            if u in best and best[u] <= t: continue
            best[u] = t
            for v, w in g[u]:
                if t + w <= maxTime:
                    heappush(pq, (cost + passingFees[v], t + w, v))
        return -1

