class Solution:
    def colorTheGrid(self, m, n):
        grid = [[-1] * n for _ in range(m)]
        def go(pos):
            if pos == m * n:
                return 1
            i, j = divmod(pos, n)
            total = 0
            for c in range(3):
                if (i and grid[i - 1][j] == c) or (j and grid[i][j - 1] == c):
                    continue
                grid[i][j] = c
                total += go(pos + 1)
                grid[i][j] = -1
            return total
        return go(0) % (10 ** 9 + 7)

