class Solution:
    def deleteDuplicateFolder(self, paths):
        root = {}
        for p in sorted(paths):
            node = root
            for name in p: node = node.setdefault(name, {})
        count, sig = Counter(), {}
        def encode(node):
            if not node: return ''
            s = ''.join('(' + k + encode(v) + ')' for k, v in sorted(node.items()))
            sig[id(node)] = s
            count[s] += 1
            return s
        encode(root)
        ans = []
        def collect(node, path):
            for k, v in node.items():
                if v and count[sig[id(v)]] > 1: continue
                ans.append(path + [k])
                collect(v, path + [k])
        collect(root, [])
        return ans

class Solution:
    def deleteDuplicateFolder(self, paths):
        root = {}
        for p in paths:
            node = root
            for name in p: node = node.setdefault(name, {})
        seen = defaultdict(list)
        def sig(node):
            return tuple((k, sig(v)) for k, v in sorted(node.items()))
        def walk(node):
            for k, v in node.items():
                if v: seen[sig(v)].append((node, k))
                walk(v)
        walk(root)
        for locs in seen.values():
            if len(locs) > 1:
                for parent, k in locs: parent.pop(k, None)
        ans = []
        def collect(node, path):
            for k, v in node.items():
                ans.append(path + [k])
                collect(v, path + [k])
        collect(root, [])
        return ans

