class Solution:
    def latestDayToCross(self, row, col, cells):
        def can(day):
            water = {(r - 1, c - 1) for r, c in cells[:day]}
            q = deque((0, c) for c in range(col) if (0, c) not in water)
            seen = set(q)
            while q:
                r, c = q.popleft()
                if r == row - 1: return True
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    a, b = r + dr, c + dc
                    if 0 <= a < row and 0 <= b < col and (a, b) not in water and (a, b) not in seen:
                        seen.add((a, b))
                        q.append((a, b))
            return False
        lo, hi = 0, len(cells)
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if can(mid): lo = mid
            else: hi = mid - 1
        return lo

class Solution:
    def latestDayToCross(self, row, col, cells):
        parent = {}
        def find(x):
            parent.setdefault(x, x)
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        land = set()
        for day in range(len(cells) - 1, -1, -1):
            r, c = cells[day][0] - 1, cells[day][1] - 1
            land.add((r, c))
            if r == 0: parent[find((r, c))] = find('T')
            if r == row - 1: parent[find((r, c))] = find('B')
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nb = (r + dr, c + dc)
                if nb in land: parent[find((r, c))] = find(nb)
            if find('T') == find('B'): return day
        return 0

