class Solution:
    def maxTaxiEarnings(self, n, rides):
        by_end = defaultdict(list)
        for s, e, t in rides: by_end[e].append((s, e - s + t))
        dp = [0] * (n + 1)
        for pos in range(1, n + 1):
            dp[pos] = dp[pos - 1]
            for s, gain in by_end[pos]: dp[pos] = max(dp[pos], dp[s] + gain)
