class Solution:
    def maxTaxiEarnings(self, n, rides):
        rides = sorted(rides)
        starts = [r[0] for r in rides]
        @lru_cache(None)
        def go(i):
            if i == len(rides): return 0
            s, e, t = rides[i]
            nxt = bisect_left(starts, e)
            return max(go(i + 1), e - s + t + go(nxt))
        return go(0)

