class Solution:
    def networkBecomesIdle(self, edges, patience):
        n = len(patience)
        g = defaultdict(list)
        for u, v in edges:
            g[u].append(v)
            g[v].append(u)
        dist = [-1] * n
        dist[0] = 0
        q = deque([0])
        while q:
            u = q.popleft()
            for v in g[u]:
                if dist[v] < 0:
                    dist[v] = dist[u] + 1
                    q.append(v)
        last = 0
        for i in range(1, n):
            rt = 2 * dist[i]
            last = max(last, rt + (rt - 1) // patience[i] * patience[i] + 1)
        return last

class Solution:
    def networkBecomesIdle(self, edges, patience):
        n = len(patience)
        g = defaultdict(list)
        for u, v in edges:
            g[u].append(v)
            g[v].append(u)
        dist = [-1] * n
        dist[0] = 0
        q = deque([0])
        while q:
            u = q.popleft()
            for v in g[u]:
                if dist[v] < 0:
                    dist[v] = dist[u] + 1
                    q.append(v)
        last = 0
        for i in range(1, n):
            rt = 2 * dist[i]
            t, finish = 0, rt
            while t + patience[i] < rt:
                t += patience[i]
                finish = t + rt
            last = max(last, finish + 1)
        return last

