        def at_most(k):
            total = 0
            for run in ''.join(c if c in 'aeiou' else ' ' for c in word).split():
                cnt, left = {}, 0
                for right, ch in enumerate(run):
                    cnt[ch] = cnt.get(ch, 0) + 1
                    while len(cnt) > k:
                        cnt[run[left]] -= 1
                        if cnt[run[left]] == 0: del cnt[run[left]]
                        left += 1
                    total += right - left + 1
            return total
