class Solution:
    def friendRequests(self, n, restrictions, requests):
        parent = list(range(n))
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        res = []
        for u, v in requests:
            pu, pv = find(u), find(v)
            ok = True
            if pu != pv:
                for x, y in restrictions:
                    px, py = find(x), find(y)
                    if (px, py) in ((pu, pv), (pv, pu)):
                        ok = False
                        break
            if ok:
                parent[pu] = pv
            res.append(ok)
        return res

class Solution:
    def friendRequests(self, n, restrictions, requests):
        adj = [set() for _ in range(n)]
        def connected(a, b):
            seen = {a}
            dq = deque([a])
            while dq:
                u = dq.popleft()
                if u == b:
                    return True
                for v in adj[u]:
                    if v not in seen:
                        seen.add(v)
                        dq.append(v)
            return False
        res = []
        for u, v in requests:
            if v in adj[u]:
                res.append(True)
                continue
            adj[u].add(v)
            adj[v].add(u)
            bad = any(connected(x, y) for x, y in restrictions)
            if bad:
                adj[u].remove(v)
                adj[v].remove(u)
            res.append(not bad)
        return res

