class Solution:
    def minimumCost(self, n, highways, discounts):
        g = defaultdict(list)
        for a, b, t in highways:
            g[a].append((b, t))
            g[b].append((a, t))
        dist = {(0, 0): 0}
        h = [(0, 0, 0)]
        while h:
            d, u, k = heappop(h)
            if u == n - 1:
                return d
            if d > dist.get((u, k), inf):
                continue
            for v, t in g[u]:
                for nk, nd in ((k, d + t), (k + 1, d + t // 2)):
                    if nk <= discounts and nd < dist.get((v, nk), inf):
                        dist[(v, nk)] = nd
                        heappush(h, (nd, v, nk))
        return -1

class Solution:
    def minimumCost(self, n, highways, discounts):
        INF = float("inf")
        dp = [[INF] * n for _ in range(discounts + 1)]
        dp[0][0] = 0
        changed = True
        while changed:
            changed = False
            for a, b, t in highways:
                for u, v in ((a, b), (b, a)):
                    for k in range(discounts + 1):
                        if dp[k][u] + t < dp[k][v]:
                            dp[k][v] = dp[k][u] + t
                            changed = True
                        if k < discounts and dp[k][u] + t // 2 < dp[k + 1][v]:
                            dp[k + 1][v] = dp[k][u] + t // 2
                            changed = True
        res = min(dp[k][n - 1] for k in range(discounts + 1))
        return -1 if res == INF else res

