class Solution:
    def maximumProfit(self, present, future, budget):
        dp = [0] * (budget + 1)
        for p, f in zip(present, future):
            gain = f - p
            if gain <= 0: continue
            for b in range(budget, p - 1, -1):
                dp[b] = max(dp[b], dp[b - p] + gain)
