        n = len(present)
        dp = [[0] * (budget + 1) for _ in range(n + 1)]
        for i in range(1, n + 1):
            p, f = present[i - 1], future[i - 1]
            for b in range(budget + 1):
                dp[i][b] = dp[i - 1][b]
                if b >= p and f > p:
                    dp[i][b] = max(dp[i][b], dp[i - 1][b - p] + f - p)
        return dp[n][budget]

