    def amountOfTime(self, root, start):
        best = 0
        def go(node):
            nonlocal best
            if not node: return 0
            l, r = go(node.left), go(node.right)
            if node.val == start:
                best = max(l, r)
                return -1
            if l >= 0 and r >= 0: return 1 + max(l, r)
            d = abs(l) if l < 0 else abs(r)
            other = r if l < 0 else l
            best = max(best, d + other)
            return -(d + 1)
        go(root)
