    def maxTastiness(self, price, tastiness, maxAmount, maxCoupons):
        n = len(price)
        @lru_cache(None)
        def f(i, money, coupons):
            if i == n: return 0
            best = f(i + 1, money, coupons)
            if money >= price[i]: best = max(best, tastiness[i] + f(i + 1, money - price[i], coupons))
            if coupons and money >= price[i] // 2: best = max(best, tastiness[i] + f(i + 1, money - price[i] // 2, coupons - 1))
            return best
