class Solution:
    def numberOfPaths(self, grid, k):
        MOD = 10 ** 9 + 7
        m, n = len(grid), len(grid[0])
        dp = [[0] * k for _ in range(n)]
        for i in range(m):
            new = [[0] * k for _ in range(n)]
            for j in range(n):
                v = grid[i][j] % k
                if i == 0 and j == 0:
                    new[0][v] = 1
                    continue
                for r in range(k):
                    ways = (dp[j][r] if i else 0) + (new[j - 1][r] if j else 0)
                    if ways: new[j][(r + v) % k] = (new[j][(r + v) % k] + ways) % MOD
            dp = new
        return dp[n - 1][0]

class Solution:
    def numberOfPaths(self, grid, k):
        MOD = 10 ** 9 + 7
        m, n = len(grid), len(grid[0])
        @lru_cache(None)
        def f(i, j, r):
            r = (r + grid[i][j]) % k
            if i == m - 1 and j == n - 1: return 1 if r == 0 else 0
            total = 0
            if i + 1 < m: total += f(i + 1, j, r)
            if j + 1 < n: total += f(i, j + 1, r)
            return total % MOD
        return f(0, 0, 0)

