class Solution:
    def treeQueries(self, root, queries):
        depth, height = {}, {}
        def go(node, d):
            if not node: return -1
            depth[node.val] = d
            height[node.val] = 1 + max(go(node.left, d + 1), go(node.right, d + 1))
            return height[node.val]
        go(root, 0)
        levels = defaultdict(list)
        for v in depth: levels[depth[v]].append((height[v], v))
        top = {}
        for d, lst in levels.items():
            lst.sort(reverse=True)
            top[d] = lst[:2]
        ans = []
        for q in queries:
            d = depth[q]
            siblings = top[d]
            if len(siblings) == 1:
                ans.append(d - 1)
            elif siblings[0][1] == q:
                ans.append(d + siblings[1][0])
            else:
                ans.append(d + siblings[0][0])
        return ans

