class Solution:
    def collectTheCoins(self, coins, edges):
        n = len(coins)
        g = defaultdict(set)
        for a, b in edges:
            g[a].add(b)
            g[b].add(a)
        deg = [len(g[i]) for i in range(n)]
        alive = set(range(n))
        q = deque(i for i in range(n) if deg[i] <= 1 and coins[i] == 0)
        queued = set(q)
        while q:
            u = q.popleft()
            alive.discard(u)
            for v in g[u]:
                if v in alive:
                    deg[v] -= 1
                    if deg[v] <= 1 and coins[v] == 0 and v not in queued:
                        queued.add(v)
                        q.append(v)
        for _ in range(2):
            leaves = [u for u in alive if deg[u] <= 1]
            for u in leaves:
                alive.discard(u)
                for v in g[u]:
                    if v in alive: deg[v] -= 1
        return 2 * max(0, len(alive) - 1)

class Solution:
    def collectTheCoins(self, coins, edges):
        n = len(coins)
        g = defaultdict(list)
        for a, b in edges:
            g[a].append(b)
            g[b].append(a)
        def bfs(s):
            dist, par, q = {s: 0}, {s: -1}, deque([s])
            while q:
                u = q.popleft()
                for v in g[u]:
                    if v not in dist:
                        dist[v], par[v] = dist[u] + 1, u
                        q.append(v)
            return dist, par
        info = [bfs(s) for s in range(n)]
        cnodes = [i for i in range(n) if coins[i]]
        if not cnodes: return 0
        opts = [[v for v in range(n) if info[c][0][v] <= 2] for c in cnodes]
        best = float('inf')
        for s in range(n):
            par = info[s][1]
            for combo in product(*opts):
                used = set()
                for t in combo:
                    u = t
                    while u != s:
                        used.add((u, par[u]))
                        u = par[u]
                best = min(best, 2 * len(used))
        return best

