class Solution:
    def numberOfWays(self, s, t, k):
        MOD = 10 ** 9 + 7
        n = len(s)
        zero, nonzero = 0, 0
        ss = s + s
        for r in range(n):
            if ss[r:r + n] == t:
                if r == 0: zero = 1
                else: nonzero += 1
        def mul(A, B):
            return [[sum(A[i][x] * B[x][j] for x in range(2)) % MOD for j in range(2)] for i in range(2)]
        M = [[0, n - 1], [1, n - 2]]
        R = [[1, 0], [0, 1]]
        e = k
        while e:
            if e & 1: R = mul(R, M)
            M = mul(M, M)
            e >>= 1
        a, b = R[0][0], R[1][0]
        return (zero * a + nonzero * b) % MOD

class Solution:
    def numberOfWays(self, s, t, k):
        MOD = 10 ** 9 + 7
        n = len(s)
        ways = [0] * n
        ways[0] = 1
        for _ in range(k):
            nxt = [0] * n
            for r in range(n):
                if ways[r]:
                    for l in range(1, n):
                        nxt[(r + l) % n] = (nxt[(r + l) % n] + ways[r]) % MOD
            ways = nxt
        ss = s + s
        return sum(ways[r] for r in range(n) if ss[r:r + n] == t) % MOD

