    def maximumXorProduct(self, a, b, n):
        MOD = 10 ** 9 + 7
        ca, cb = (a >> n) << n, (b >> n) << n
        for bit in range(n - 1, -1, -1):
            ba, bb = a >> bit & 1, b >> bit & 1
            if ba == bb:
                ca |= 1 << bit
                cb |= 1 << bit
            elif ca <= cb: ca |= 1 << bit
            else: cb |= 1 << bit
        return ca * cb % MOD

class Solution:
    def maximumXorProduct(self, a, b, n):
        best = 0
        for x in range(1 << n): best = max(best, (a ^ x) * (b ^ x))
        return best % (10 ** 9 + 7)

