class Solution:
    def lexicographicallySmallestArray(self, nums, limit):
        order = sorted(range(len(nums)), key=lambda i: nums[i])
        groups = [[order[0]]]
        for a, b in zip(order, order[1:]):
            if nums[b] - nums[a] <= limit: groups[-1].append(b)
            else: groups.append([b])
        res = nums[:]
        for g in groups:
            vals = sorted(nums[i] for i in g)
            for i, v in zip(sorted(g), vals): res[i] = v
        return res

class Solution:
    def lexicographicallySmallestArray(self, nums, limit):
        n = len(nums)
        seen = [False] * n
        res = nums[:]
        for s in range(n):
            if seen[s]: continue
            comp, st = [], [s]
            seen[s] = True
            while st:
                u = st.pop()
                comp.append(u)
                for v in range(n):
                    if not seen[v] and abs(nums[u] - nums[v]) <= limit:
                        seen[v] = True
                        st.append(v)
            for i, v in zip(sorted(comp), sorted(nums[i] for i in comp)): res[i] = v
        return res

