class Solution:
    def numberOfSequence(self, n, sick):
        MOD = 10 ** 9 + 7
        gaps = [sick[0], n - 1 - sick[-1]]
        mid = [sick[i + 1] - sick[i] - 1 for i in range(len(sick) - 1)]
        m = n - len(sick)
        ans = factorial(m) % MOD
        for g in gaps + mid:
            if g > 0: ans = ans * pow(factorial(g), MOD - 2, MOD) % MOD
        for g in mid:
            if g > 0: ans = ans * pow(2, g - 1, MOD) % MOD
        return ans

class Solution:
    def numberOfSequence(self, n, sick):
        MOD = 10 ** 9 + 7
        start = sum(1 << s for s in sick)
        full = (1 << n) - 1
        @lru_cache(None)
        def f(mask):
            if mask == full: return 1
            total = 0
            for i in range(n):
                if not mask >> i & 1 and ((i > 0 and mask >> (i - 1) & 1) or (i + 1 < n and mask >> (i + 1) & 1)):
                    total += f(mask | 1 << i)
            return total % MOD
        return f(start)

