class Solution:
    def numberOfSets(self, n, maxDistance, roads):
        INF = float('inf')
        count = 0
        for mask in range(1 << n):
            nodes = [i for i in range(n) if mask >> i & 1]
            dist = {(a, b): (0 if a == b else INF) for a in nodes for b in nodes}
            for u, v, w in roads:
                if mask >> u & 1 and mask >> v & 1:
                    dist[(u, v)] = min(dist[(u, v)], w)
                    dist[(v, u)] = min(dist[(v, u)], w)
            for k in nodes:
                for i in nodes:
                    for j in nodes:
                        if dist[(i, k)] + dist[(k, j)] < dist[(i, j)]: dist[(i, j)] = dist[(i, k)] + dist[(k, j)]
            if all(dist[(a, b)] <= maxDistance for a in nodes for b in nodes): count += 1
        return count

class Solution:
    def numberOfSets(self, n, maxDistance, roads):
        count = 0
        for mask in range(1 << n):
            keep = [i for i in range(n) if mask >> i & 1]
            adj = defaultdict(list)
            for u, v, w in roads:
                if mask >> u & 1 and mask >> v & 1:
                    adj[u].append((v, w))
                    adj[v].append((u, w))
            ok = True
            for s in keep:
                dist = {s: 0}
                pq = [(0, s)]
                while pq:
                    d, u = heappop(pq)
                    if d > dist[u]: continue
                    for v, w in adj[u]:
                        if d + w < dist.get(v, float('inf')):
                            dist[v] = d + w
                            heappush(pq, (d + w, v))
                if any(dist.get(t, float('inf')) > maxDistance for t in keep):
                    ok = False
                    break
            if ok: count += 1
        return count

