class Solution:
    def minimumCost(self, source, target, original, changed, cost):
        INF = float('inf')
        d = [[INF] * 26 for _ in range(26)]
        for i in range(26): d[i][i] = 0
        for a, b, c in zip(original, changed, cost):
            x, y = ord(a) - 97, ord(b) - 97
            d[x][y] = min(d[x][y], c)
        for k in range(26):
            for i in range(26):
                for j in range(26):
                    if d[i][k] + d[k][j] < d[i][j]: d[i][j] = d[i][k] + d[k][j]
        total = 0
        for s, t in zip(source, target):
            c = d[ord(s) - 97][ord(t) - 97]
            if c == INF: return -1
            total += c
        return total

class Solution:
    def minimumCost(self, source, target, original, changed, cost):
        g = defaultdict(list)
        for a, b, c in zip(original, changed, cost): g[a].append((b, c))
        memo = {}
        def dist_from(s):
            if s in memo: return memo[s]
            dist = {s: 0}
            pq = [(0, s)]
            while pq:
                d, u = heappop(pq)
                if d > dist[u]: continue
                for v, w in g[u]:
                    if d + w < dist.get(v, float('inf')):
                        dist[v] = d + w
                        heappush(pq, (d + w, v))
            memo[s] = dist
            return dist
        total = 0
        for s, t in zip(source, target):
            d = dist_from(s).get(t)
            if d is None: return -1
            total += d
        return total

