class Solution:
    def minimumCost(self, source, target, original, changed, cost):
        ids = {}
        for s in original + changed: ids.setdefault(s, len(ids))
        k = len(ids)
        INF = float('inf')
        d = [[INF] * k for _ in range(k)]
        for i in range(k): d[i][i] = 0
        for a, b, c in zip(original, changed, cost): d[ids[a]][ids[b]] = min(d[ids[a]][ids[b]], c)
        for m in range(k):
            for i in range(k):
                for j in range(k):
                    if d[i][m] + d[m][j] < d[i][j]: d[i][j] = d[i][m] + d[m][j]
        lengths = sorted({len(s) for s in ids})
        n = len(source)
        dp = [INF] * (n + 1)
        dp[0] = 0
        for i in range(n):
            if dp[i] == INF: continue
            if source[i] == target[i]: dp[i + 1] = min(dp[i + 1], dp[i])
            for L in lengths:
                if i + L > n: break
                a, b = source[i:i + L], target[i:i + L]
                if a in ids and b in ids and d[ids[a]][ids[b]] < INF:
                    dp[i + L] = min(dp[i + L], dp[i] + d[ids[a]][ids[b]])
        return dp[n] if dp[n] < INF else -1

class Solution:
    def minimumCost(self, source, target, original, changed, cost):
        g = defaultdict(list)
        for a, b, c in zip(original, changed, cost): g[a].append((b, c))
        memo = {}
        def dist(s, t):
            if s not in memo:
                dd = {s: 0}
                pq = [(0, s)]
                while pq:
                    d, u = heappop(pq)
                    if d > dd[u]: continue
                    for v, w in g[u]:
                        if d + w < dd.get(v, float('inf')):
                            dd[v] = d + w
                            heappush(pq, (d + w, v))
                memo[s] = dd
            return memo[s].get(t, float('inf'))
        lengths = sorted({len(s) for s in original})
        n = len(source)
        @lru_cache(None)
        def go(i):
            if i == n: return 0
            best = float('inf')
            if source[i] == target[i]: best = go(i + 1)
            for L in lengths:
                if i + L > n: break
                d = dist(source[i:i + L], target[i:i + L])
                if d < float('inf'): best = min(best, d + go(i + L))
            return best
        ans = go(0)
        return ans if ans < float('inf') else -1

