class Solution:
    def maximumSubarraySum(self, nums, k):
        best_pre = {}
        pre, ans = 0, float('-inf')
        for x in nums:
            for v in (x - k, x + k):
                if v in best_pre: ans = max(ans, pre + x - best_pre[v])
            if x not in best_pre or pre < best_pre[x]: best_pre[x] = pre
            pre += x
        return ans if ans != float('-inf') else 0

class Solution:
    def maximumSubarraySum(self, nums, k):
        pre = [0]
        for x in nums: pre.append(pre[-1] + x)
        best = float('-inf')
        for i in range(len(nums)):
            for j in range(i + 1, len(nums)):
                if abs(nums[i] - nums[j]) == k: best = max(best, pre[j + 1] - pre[i])
        return best if best != float('-inf') else 0

