class Solution:
    def resultGrid(self, image, threshold):
        m, n = len(image), len(image[0])
        total = [[0] * n for _ in range(m)]
        cnt = [[0] * n for _ in range(m)]
        for i in range(m - 2):
            for j in range(n - 2):
                ok = all(abs(image[a][b] - image[a][b + 1]) <= threshold for a in range(i, i + 3) for b in range(j, j + 2))
                ok = ok and all(abs(image[a][b] - image[a + 1][b]) <= threshold for a in range(i, i + 2) for b in range(j, j + 3))
                if ok:
                    avg = sum(image[a][b] for a in range(i, i + 3) for b in range(j, j + 3)) // 9
                    for a in range(i, i + 3):
                        for b in range(j, j + 3):
                            total[a][b] += avg
                            cnt[a][b] += 1
        return [[total[i][j] // cnt[i][j] if cnt[i][j] else image[i][j] for j in range(n)] for i in range(m)]

class Solution:
    def resultGrid(self, image, threshold):
        m, n = len(image), len(image[0])
        def good(i, j):
            for a in range(i, i + 3):
                for b in range(j, j + 3):
                    if b + 1 < j + 3 and abs(image[a][b] - image[a][b + 1]) > threshold: return False
                    if a + 1 < i + 3 and abs(image[a][b] - image[a + 1][b]) > threshold: return False
            return True
        res = []
        for x in range(m):
            row = []
            for y in range(n):
                avgs = []
                for i in range(x - 2, x + 1):
                    for j in range(y - 2, y + 1):
                        if 0 <= i <= m - 3 and 0 <= j <= n - 3 and good(i, j):
                            avgs.append(sum(image[a][b] for a in range(i, i + 3) for b in range(j, j + 3)) // 9)
                row.append(sum(avgs) // len(avgs) if avgs else image[x][y])
            res.append(row)
        return res

