class Solution:
    def minimumOperationsToWriteY(self, grid):
        n = len(grid)
        c = n // 2
        y, other = Counter(), Counter()
        for i in range(n):
            for j in range(n):
                on_y = (i <= c and (i == j or i + j == n - 1)) or (i >= c and j == c)
                (y if on_y else other)[grid[i][j]] += 1
        ny, no = sum(y.values()), sum(other.values())
        best = float('inf')
        for a in range(3):
            for b in range(3):
                if a != b:
                    best = min(best, (ny - y[a]) + (no - other[b]))
        return best

class Solution:
    def minimumOperationsToWriteY(self, grid):
        n = len(grid)
        c = n // 2
        def on_y(i, j): return (i <= c and (i == j or i + j == n - 1)) or (i >= c and j == c)
        best = float('inf')
        for a in range(3):
            for b in range(3):
                if a == b: continue
                ops = 0
                for i in range(n):
                    for j in range(n):
                        want = a if on_y(i, j) else b
                        if grid[i][j] != want: ops += 1
                best = min(best, ops)
        return best

