class Solution:
    def resultArray(self, nums):
        vals = sorted(set(nums))
        rank = {v: i + 1 for i, v in enumerate(vals)}
        m = len(vals)
        def add(tree, i):
            while i <= m:
                tree[i] += 1
                i += i & -i
        def prefix(tree, i):
            s = 0
            while i > 0:
                s += tree[i]
                i -= i & -i
            return s
        t1, t2 = [0] * (m + 1), [0] * (m + 1)
        a, b = [nums[0]], [nums[1]]
        add(t1, rank[nums[0]])
        add(t2, rank[nums[1]])
        for x in nums[2:]:
            r = rank[x]
            g1 = len(a) - prefix(t1, r)
            g2 = len(b) - prefix(t2, r)
            if g1 > g2 or (g1 == g2 and len(a) <= len(b)):
                a.append(x)
                add(t1, r)
            else:
                b.append(x)
                add(t2, r)
        return a + b

class Solution:
    def resultArray(self, nums):
        a, b = [nums[0]], [nums[1]]
        sa, sb = [nums[0]], [nums[1]]
        for x in nums[2:]:
            g1 = len(sa) - bisect_right(sa, x)
            g2 = len(sb) - bisect_right(sb, x)
            if g1 > g2 or (g1 == g2 and len(a) <= len(b)):
                a.append(x)
                insort(sa, x)
            else:
                b.append(x)
                insort(sb, x)
        return a + b

