class Solution:
    def maximumTripletValue(self, nums):
        n = len(nums)
        sufmax = [0] * (n + 1)
        for i in range(n - 1, -1, -1): sufmax[i] = max(sufmax[i + 1], nums[i])
        seen, ans = [], float('-inf')
        for j in range(n):
            idx = bisect_left(seen, nums[j])
            if idx > 0 and sufmax[j + 1] > nums[j]: ans = max(ans, seen[idx - 1] - nums[j] + sufmax[j + 1])
            insort(seen, nums[j])
        return ans

