class Solution:
    def findPattern(self, board, pattern):
        R, C = len(pattern), len(pattern[0])
        for i in range(len(board) - R + 1):
            for j in range(len(board[0]) - C + 1):
                mp, ok = {}, True
                for a in range(R):
                    for b in range(C):
                        p, v = pattern[a][b], board[i + a][j + b]
                        if p.isdigit():
                            if int(p) != v: ok = False
                        elif mp.setdefault(p, v) != v: ok = False
                if ok:
                    digits = {int(p) for row in pattern for p in row if p.isdigit()}
                    if len(set(mp.values())) == len(mp) and not (set(mp.values()) & digits): return [i, j]
        return [-1, -1]

class Solution:
    def findPattern(self, board, pattern):
        R, C = len(pattern), len(pattern[0])
        for i in range(len(board) - R + 1):
            for j in range(len(board[0]) - C + 1):
                m, rev, ok = {}, {}, True
                for a in range(R):
                    for b in range(C):
                        p, v = pattern[a][b], board[i + a][j + b]
                        if p.isdigit() and int(p) != v: ok = False
                        if m.setdefault(p, v) != v or rev.setdefault(v, p) != p: ok = False
                if ok: return [i, j]
        return [-1, -1]

