class Solution:
    def mostFrequentIDs(self, nums, freq):
        cnt, heap, ans = defaultdict(int), [], []
        for x, f in zip(nums, freq):
            cnt[x] += f
            heappush(heap, (-cnt[x], x))
            while -heap[0][0] != cnt[heap[0][1]]: heappop(heap)
            ans.append(-heap[0][0])
        return ans

