class Solution:
    def getSmallestString(self, s, k):
        out = []
        for ch in s:
            x = ord(ch) - 97
            for t in range(26):
                cost = min(abs(x - t), 26 - abs(x - t))
                if cost <= k:
                    out.append(chr(97 + t))
                    k -= cost
                    break
        return ''.join(out)

