        i = score = 0
        while 0 <= i < n and i not in seen:
            seen.add(i)
            if instructions[i] == 'add':
                score += values[i]
                i += 1
            else:
                i += values[i]
        return score

class Solution:
    def calculateScore(self, instructions, values):
        n = len(instructions)
        path, seen = [], [False] * n
        i = 0
        while 0 <= i < n and not seen[i]:
            seen[i] = True
            path.append(i)
            i += 1 if instructions[i] == 'add' else values[i]
        return sum(values[j] for j in path if instructions[j] == 'add')

