class Solution:
    def queryConversions(self, conversions, queries):
        MOD = 10 ** 9 + 7
        n = len(conversions) + 1
        g = defaultdict(list)
        for s, t, f in conversions:
            g[s].append((t, f))
            g[t].append((s, pow(f, MOD - 2, MOD)))
        ratio = [0] * n
        ratio[0] = 1
        q = deque([0])
        while q:
            u = q.popleft()
            for v, f in g[u]:
                if not ratio[v]:
                    ratio[v] = ratio[u] * f % MOD
                    q.append(v)
        return [ratio[b] * pow(ratio[a], MOD - 2, MOD) % MOD for a, b in queries]

class Solution:
    def queryConversions(self, conversions, queries):
        MOD = 10 ** 9 + 7
        g = defaultdict(list)
        for s, t, f in conversions:
            g[s].append((t, f))
            g[t].append((s, pow(f, MOD - 2, MOD)))
        res = []
        for a, b in queries:
            val = {a: 1}
            st = [a]
            while st:
                u = st.pop()
                for v, f in g[u]:
                    if v not in val:
                        val[v] = val[u] * f % MOD
                        st.append(v)
            res.append(val[b])
        return res

