class Solution:
    def minCost(self, n, edges, k):
        def comps(w):
            parent = list(range(n))
            def find(x):
                while parent[x] != x:
                    parent[x] = parent[parent[x]]
                    x = parent[x]
                return x
            c = n
            for u, v, wt in edges:
                if wt <= w:
                    ru, rv = find(u), find(v)
                    if ru != rv:
                        parent[ru] = rv
                        c -= 1
            return c
        cands = sorted({0} | {e[2] for e in edges})
        lo, hi = 0, len(cands) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if comps(cands[mid]) <= k: hi = mid
            else: lo = mid + 1
        return cands[lo]

