class Solution:
    def minJumps(self, nums):
        n = len(nums)
        def factors(x):
            ps, d = set(), 2
            while d * d <= x:
                if x % d == 0:
                    ps.add(d)
                    while x % d == 0: x //= d
                d += 1
            if x > 1: ps.add(x)
            return ps
        pos = defaultdict(list)
        for i, x in enumerate(nums):
            for p in factors(x): pos[p].append(i)
        dist = [-1] * n
        dist[0] = 0
        q = deque([0])
        while q:
            i = q.popleft()
            nb = [i - 1, i + 1]
            if factors(nums[i]) == {nums[i]}:
                nb += pos[nums[i]]
                pos[nums[i]] = []
            for j in nb:
                if 0 <= j < n and dist[j] < 0:
                    dist[j] = dist[i] + 1
                    q.append(j)
        return dist[n - 1]

class Solution:
    def minJumps(self, nums):
        n = len(nums)
        def prime(x):
            return x > 1 and all(x % d for d in range(2, int(x ** 0.5) + 1))
        dist = [-1] * n
        dist[0] = 0
        q = deque([0])
        while q:
            i = q.popleft()
            nb = [i - 1, i + 1]
            if prime(nums[i]): nb += [j for j in range(n) if nums[j] % nums[i] == 0 and j != i]
            for j in nb:
                if 0 <= j < n and dist[j] < 0:
                    dist[j] = dist[i] + 1
                    q.append(j)
        return dist[n - 1]

