class Solution:
    def countSequences(self, nums, k):
        states = {Fraction(1): 1}
        for x in nums:
            new = defaultdict(int)
            for v, c in states.items():
                new[v] += c
                new[v * x] += c
                new[v / x] += c
            states = new
        return states.get(Fraction(k), 0)

