class Solution:
    def countSequences(self, nums, k):
        count = 0
        for choice in product((0, 1, 2), repeat=len(nums)):
            v = Fraction(1)
            for c, x in zip(choice, nums):
                if c == 1: v *= x
                elif c == 2: v /= x
            if v == k: count += 1
        return count

