class Solution:
    def minimumIncrease(self, nums):
        n = len(nums)
        if n < 3: return 0
        cost = lambda i: max(0, max(nums[i - 1], nums[i + 1]) + 1 - nums[i])
        if n % 2 == 1: return sum(cost(i) for i in range(1, n - 1, 2))
        m = (n - 2) // 2
        pre = [0]
        for j in range(1, m + 1): pre.append(pre[-1] + cost(2 * j - 1))
        suf = [0]
        for u in range(1, m + 1): suf.append(suf[-1] + cost(n - 2 * u))
        return min(pre[j] + suf[m - j] for j in range(m + 1))

class Solution:
    def minimumIncrease(self, nums):
        n = len(nums)
        if n < 3: return 0
        m = (n - 1) // 2
        cost = lambda i: max(0, max(nums[i - 1], nums[i + 1]) + 1 - nums[i])
        INF = float('inf')
        @lru_cache(None)
        def f(i, c):
            if c == 0: return 0
            if i > n - 2: return INF
            return min(f(i + 1, c), cost(i) + f(i + 2, c - 1))
        return f(1, m)

