class Solution:
    def maxScore(self, nums, maxVal):
        n = len(nums)
        M = max(max(nums), maxVal)
        freq = [0] * (M + 1)
        for x in nums: freq[x] += 1
        cnt = [0] * (M + 1)
        for d in range(1, M + 1):
            for m in range(d, M + 1, d): cnt[d] += freq[m]
        mu = [1] * (M + 1)
        isp = [True] * (M + 1)
        for p in range(2, M + 1):
            if isp[p]:
                for m in range(p, M + 1, p):
                    if m > p: isp[m] = False
                    mu[m] = -mu[m]
                for m in range(p * p, M + 1, p * p): mu[m] = 0
        coprime = [0] * (M + 1)
        for d in range(1, M + 1):
            if mu[d]:
                for m in range(d, M + 1, d): coprime[m] += mu[d] * cnt[d]
        best = float('-inf')
        for v in range(1, maxVal + 1):
            bad = n - coprime[v]
            cost = 1 if bad == 0 else bad
            if freq[v]: cost = min(cost, bad - (1 if v > 1 else 0))
            best = max(best, v - cost)
        return best

class Solution:
    def maxScore(self, nums, maxVal):
        n, best = len(nums), float('-inf')
        for i in range(n):
            for v in range(1, maxVal + 1):
                cost = (v != nums[i]) + sum(1 for j in range(n) if j != i and gcd(nums[j], v) > 1)
                best = max(best, v - cost)
        return best
